---firewall---
 ipv4 {
     forward {
         filter {
             default-action drop
             rule 5 {
                 action accept
             }
             rule 10 {
                 action accept
                 inbound-interface {
                     name eth1
                 }
                 outbound-interface {
                     name eth2
                 }
             }
             rule 20 {
                 action accept
                 inbound-interface {
                     name eth2
                 }
                 outbound-interface {
                     name eth1
                 }
             }
         }
     }
 }

